function upper(strings, ...values) {
  var result = '';
  strings.forEach(function (str, i) {
    result += str;
    if (i < values.length) {
      result += String(values[i]).toUpperCase();
    }
  });
  return result;
}
var name = 'kyle';
console.log(upper`Hello, ${name}!`);

